package com.campus.system.controller;

import com.campus.system.model.*; import com.campus.system.repository.*;
import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import java.time.LocalDateTime; import java.util.*;

@RestController @RequestMapping("/api")
public class ContestController {
 private final ContestRepository contests; private final ContestParticipantRepository participants; private final SubmissionRepository submissions;
 public ContestController(ContestRepository c,ContestParticipantRepository p,SubmissionRepository s){contests=c;participants=p;submissions=s;}
 private boolean staff(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_FACULTY")||x.getAuthority().equals("ROLE_ADMIN"));}
 @GetMapping("/contests") public List<Map<String,Object>> list(Authentication a){return contests.findAllByOrderByStartTimeAsc().stream().map(c->view(c,a.getName())).toList();}
 @PostMapping("/contests") public ResponseEntity<?> create(@RequestBody Map<String,Object> body,Authentication a){if(!staff(a))return ResponseEntity.status(403).body(Map.of("message","Faculty or Admin access required"));
  String title=str(body,"title"),subject=str(body,"subject"); if(title.isBlank()||subject.isBlank())return ResponseEntity.badRequest().body(Map.of("message","Title and subject are required"));
  Contest c=new Contest();c.setTitle(title);c.setSubject(subject);c.setDescription(str(body,"description"));c.setLevel(or(str(body,"level"),"Intermediate"));c.setDurationMinutes(num(body,"durationMinutes",60));c.setMaxScore(100);c.setCreatedBy(a.getName());
  c.setStartTime(parse(body.get("startTime"))); c.setEndTime(parse(body.get("endTime"))); c.setStatus(c.getStartTime()!=null&&c.getStartTime().isAfter(LocalDateTime.now())?"UPCOMING":"LIVE");
  return ResponseEntity.ok(view(contests.save(c),a.getName())); }
 @GetMapping("/contests/{id}") public ResponseEntity<?> detail(@PathVariable Long id,Authentication a){return contests.findById(id).<ResponseEntity<?>>map(c->ResponseEntity.ok(view(c,a.getName()))).orElseGet(()->ResponseEntity.notFound().build());}
 @PostMapping("/contests/{id}/join") public ResponseEntity<?> join(@PathVariable Long id,Authentication a){Contest c=contests.findById(id).orElse(null);if(c==null)return ResponseEntity.notFound().build();if(participants.existsByContestIdAndUsername(id,a.getName()))return ResponseEntity.ok(Map.of("message","Already joined"));ContestParticipant p=new ContestParticipant();p.setContest(c);p.setUsername(a.getName());participants.save(p);return ResponseEntity.ok(Map.of("message","Successfully joined contest","participants",participants.countByContestId(id)));}
 @PostMapping("/contests/{id}/submissions") public ResponseEntity<?> submit(@PathVariable Long id,@RequestBody Map<String,String> body,Authentication a){Contest c=contests.findById(id).orElse(null);if(c==null)return ResponseEntity.notFound().build();if(!participants.existsByContestIdAndUsername(id,a.getName()))return ResponseEntity.status(403).body(Map.of("message","Join the contest before submitting"));String code=body.getOrDefault("sourceCode","");if(code.isBlank())return ResponseEntity.badRequest().body(Map.of("message","Source code is required"));if(code.length()>20000)return ResponseEntity.badRequest().body(Map.of("message","Code limit is 20,000 characters"));
  // Safe classroom rubric simulation: source is assessed as text; arbitrary code is never executed on the server.
  int score=0;String lower=code.toLowerCase();if(code.length()>30)score+=20;if(lower.contains("class ")||lower.contains("def ")||lower.contains("function ")||lower.contains("public static"))score+=20;if(lower.contains("return")||lower.contains("print")||lower.contains("console.log"))score+=20;if(lower.contains("if")||lower.contains("for")||lower.contains("while"))score+=20;if(lower.contains("//")||lower.contains("#")||lower.contains("/*"))score+=10;if(code.trim().length()>120)score+=10;score=Math.min(100,score);
  Submission sub=new Submission();sub.setContest(c);sub.setUsername(a.getName());sub.setSourceCode(code);sub.setLanguage(body.getOrDefault("language","java"));sub.setScore(score);sub.setStatus("EVALUATED");sub.setFeedback("Classroom demo evaluation completed using a source-structure rubric. Arbitrary code execution is disabled for safety.");submissions.save(sub);return ResponseEntity.ok(submissionView(sub)); }
 @GetMapping("/submissions/mine") public List<Map<String,Object>> mine(Authentication a){return submissions.findByUsernameOrderBySubmittedAtDesc(a.getName()).stream().map(this::submissionView).toList();}
 @GetMapping("/leaderboard") public List<Map<String,Object>> leaderboard(){Map<String,Integer> scores=new HashMap<>();Map<String,Long> counts=new HashMap<>();for(Submission s:submissions.findAll()){scores.merge(s.getUsername(),s.getScore(),Integer::sum);counts.merge(s.getUsername(),1L,Long::sum);}List<Map<String,Object>> out=new ArrayList<>();scores.entrySet().stream().sorted(Map.Entry.<String,Integer>comparingByValue().reversed()).limit(50).forEach(e->out.add(Map.of("username",e.getKey(),"points",e.getValue(),"submissions",counts.getOrDefault(e.getKey(),0L))));return out;}
 @GetMapping("/analytics/mine") public Map<String,Object> analytics(Authentication a){List<Submission> list=submissions.findByUsernameOrderBySubmittedAtDesc(a.getName());Map<String,List<Integer>> by=new LinkedHashMap<>();for(String s:List.of("DSA","FSD","DBMS","CN","CC"))by.put(s,new ArrayList<>());for(Submission sub:list)by.computeIfAbsent(sub.getContest().getSubject(),k->new ArrayList<>()).add(sub.getScore());Map<String,Object> subject=new LinkedHashMap<>();by.forEach((k,v)->subject.put(k,v.isEmpty()?0:(int)Math.round(v.stream().mapToInt(Integer::intValue).average().orElse(0))));int total=list.stream().mapToInt(Submission::getScore).sum();return Map.of("totalSubmissions",list.size(),"averageScore",list.isEmpty()?0:(int)Math.round(list.stream().mapToInt(Submission::getScore).average().orElse(0)),"totalPoints",total,"subjects",subject);}
 private Map<String,Object> view(Contest c,String username){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("title",c.getTitle());m.put("subject",c.getSubject());m.put("description",c.getDescription()==null?"":c.getDescription());m.put("level",c.getLevel()==null?"Intermediate":c.getLevel());m.put("status",c.getStatus());m.put("durationMinutes",c.getDurationMinutes()==null?60:c.getDurationMinutes());m.put("participants",participants.countByContestId(c.getId()));m.put("joined",participants.existsByContestIdAndUsername(c.getId(),username));m.put("startTime",c.getStartTime()==null?"":c.getStartTime().toString());m.put("endTime",c.getEndTime()==null?"":c.getEndTime().toString());return m;}
 private Map<String,Object> submissionView(Submission s){return Map.of("id",s.getId(),"contestId",s.getContest().getId(),"contestTitle",s.getContest().getTitle(),"subject",s.getContest().getSubject(),"username",s.getUsername(),"language",s.getLanguage(),"score",s.getScore(),"status",s.getStatus(),"feedback",s.getFeedback(),"submittedAt",s.getSubmittedAt().toString());}
 private String str(Map<String,Object> m,String k){Object v=m.get(k);return v==null?"":v.toString().trim();} private String or(String v,String d){return v.isBlank()?d:v;} private int num(Map<String,Object> m,String k,int d){try{return Integer.parseInt(String.valueOf(m.get(k)));}catch(Exception e){return d;}} private LocalDateTime parse(Object v){try{return v==null||v.toString().isBlank()?null:LocalDateTime.parse(v.toString());}catch(Exception e){return null;}}
}
